    points.forEach(function (point) {
        pm.expect(point.ts).to.be.a("number");
        pm.expect(point).to.have.property("value");
    });
});

pm.test("历史点按时间升序排列", function () {
    for (let i = 1; i < points.length; i++) {
        pm.expect(points[i].ts).to.be.at.least(points[i - 1].ts);
    }
});

